CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS camera_work_shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operator_id uuid NOT NULL, work_date date NOT NULL, start_time time NOT NULL, end_time time NOT NULL, status text NOT NULL DEFAULT 'planned', camera_object_id uuid, comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS camera_violations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_datetime timestamptz NOT NULL, author_id uuid NOT NULL, camera_object_id uuid, status text NOT NULL DEFAULT 'new', severity text, comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS camera_violation_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), violation_id uuid NOT NULL REFERENCES camera_violations(id) ON DELETE CASCADE, object_key text NOT NULL, original_file_name text NOT NULL, mime_type text NOT NULL, file_size bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL UNIQUE, event_type text NOT NULL, event_version integer NOT NULL DEFAULT 1, aggregate_type text NOT NULL, aggregate_id text NOT NULL, correlation_id text NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0, last_error text);
